#!/usr/bin/env bash
# Generated by scripts/build_skill_shell_templates.py; edit a separate copy.
set -euo pipefail

if (( $# > 1 )); then
  printf 'Usage: bash %s [plan|doctor|execute]\n' "$0" >&2
  exit 2
fi
case "${1:-plan}" in
  -h|--help)
    printf 'Usage: bash %s [plan|doctor|execute]\n' "$0"
    printf '%s\n' 'Set SLICER, REPO, SUBJECT, SUBJECT_ID, OUTPUTS and ASSETS first.'
    printf '%s\n' 'Optional: export DEPENDENCY_CONFIG for saved GUI dependency paths.'
    exit 0 ;;
  plan) TEMPLATE_MODE_FLAG=--plan ;;
  doctor) TEMPLATE_MODE_FLAG=--doctor ;;
  execute) TEMPLATE_MODE_FLAG=--execute ;;
  *) printf 'Unknown mode: %s\n' "$1" >&2; exit 2 ;;
esac

: "${SLICER:?Set SLICER to the actual Slicer launcher}"
: "${REPO:?Set REPO to the checkout or installed runtime root}"
: "${SUBJECT:?Set SUBJECT to a prepared subject directory}"
: "${SUBJECT_ID:?Set SUBJECT_ID to this subject identifier}"
: "${OUTPUTS:?Set OUTPUTS to the parent directory for route-specific outputs}"
: "${ASSETS:?Set ASSETS to the confirmed model/resource root}"

pipeline() {
  local run_name="$1"
  shift
  local arg
  local route_args=()
  for arg in "$@"; do
    if [[ "$arg" == --plan ]]; then
      route_args+=("$TEMPLATE_MODE_FLAG")
    else
      route_args+=("$arg")
    fi
  done
  local command=("$SLICER" --launch PythonSlicer "$REPO/shared/run_subject_pipeline_cli.py"
    --no-user-config --strict-environment
    --subject-root "$SUBJECT" --subject-id "$SUBJECT_ID"
    --output-root "$OUTPUTS/$run_name" --run-name "$run_name"
    --model-assets-dir "$ASSETS")
  if [[ -n "${DEPENDENCY_CONFIG:-}" ]]; then
    command+=(--dependency-config "$DEPENDENCY_CONFIG")
  fi
  command+=("${route_args[@]}")
  if [[ "$TEMPLATE_MODE_FLAG" == --execute ]]; then
    for arg in "${command[@]}"; do
      if [[ "$arg" == *'/path/to/'* ]]; then
        printf 'Replace the example path before execution: %s\n' "$arg" >&2
        return 2
      fi
    done
  fi
  "${command[@]}"
}

